using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Threading;
namespace FlowShift {
public static class WheelNavigationTests {
 [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct NativeMouse {public int x,y;public uint data,flags,time;public IntPtr extra;}
 [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct NativeKey {public ushort vk,scan;public uint flags,time;public IntPtr extra;}
 [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Explicit,Size=40)]struct NativeInput {[System.Runtime.InteropServices.FieldOffset(0)]public uint type;[System.Runtime.InteropServices.FieldOffset(8)]public NativeMouse mouse;[System.Runtime.InteropServices.FieldOffset(8)]public NativeKey key;}
 [System.Runtime.InteropServices.DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint count,NativeInput[] inputs,int size);
 static void PumpUntil(Window window,Func<bool> complete){var frame=new DispatcherFrame();var deadline=DateTime.UtcNow.AddSeconds(2);var timer=new DispatcherTimer(){Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(s,e)=>{if(complete()||DateTime.UtcNow>deadline){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);Drain(window);}
 static void Drain(Window window){window.UpdateLayout();window.Dispatcher.Invoke(new Action(()=>{}),DispatcherPriority.ApplicationIdle);window.UpdateLayout();}
 static uint Data(int delta){return unchecked((uint)(ushort)(short)delta<<16);}
 public static int Run(string dir){Directory.CreateDirectory(dir);Preferences.Home=Path.Combine(dir,"profile");var log=new List<string>();Action<bool,string> check=(valid,name)=>{if(!valid)throw new Exception("FAIL "+name);log.Add("PASS "+name);};Application app=null;try{
  var routes="png webp pdf jpg ico bmp tiff avif zip txt docx html gif svg wav mp3 mp4 json csv xlsx 7z tar tgz epub odt".Split(' ').Select(f=>new Route(f,"","")).ToList();var pref=new Preferences();var pages=WheelPresets.Build(pref,routes,"Image");check(pages.Count==4,"default one-page preset automatically exposes all four format pages");check(new HashSet<string>(pages.SelectMany(p=>p).Where(f=>f!=WheelModel.More)).SetEquals(routes.Select(r=>r.Format)),"every usable target is reachable from wheel pages");check(pages.All(p=>p.Last()==WheelModel.More&&p.Length<=8),"each generated page retains more and at most seven formats");check(pages.SelectMany(p=>p.Where(f=>f!=WheelModel.More)).Distinct().Count()==routes.Count,"automatic pages do not repeat formats");
  pref.WheelLayouts["Image"]=new List<string[]>{new[]{"avif","webp","png","pdf","jpg","bmp","tiff"}};pages=WheelPresets.Build(pref,routes,"Image");check(pages[0][0]=="avif"&&pages.Count>1,"existing custom first page survives automatic continuation");check(WheelPresets.Build(new Preferences(),new[]{new Route("zip","","")},"Mixed").Count==1,"a single reachable target is genuinely one page");check(WheelNavigation.WheelDelta(Data(-120))==-120&&WheelNavigation.WheelDelta(Data(240))==240,"decode signed native scroll deltas");
  var scroll=new WheelScroll();check(scroll.Steps(-40)==0&&scroll.Steps(-40)==0&&scroll.Steps(-40)==1,"high-resolution wheel accumulates partial deltas");check(scroll.Steps(240)==-2,"fast scroll supports two-page steps");
  app=new Application(){ShutdownMode=ShutdownMode.OnExplicitShutdown};var main=new MainWindow(true);main.Show();var field=new TextBox(){Text="background focus remains here"};var background=new Window(){Content=field,Width=360,Height=160,ShowInTaskbar=false};background.Show();var wheel=new RadialCompass(new[]{"photo.jpg"},routes,"Image",0,null,true,new Preferences()){ShowActivated=false};wheel.Show();main.activeWheel=wheel;background.Activate();field.Focus();Keyboard.Focus(field);Drain(background);check(field.IsKeyboardFocused,"test focus belongs to another window rather than wheel");
  check(main.NavigateWheelMouse(0x20A,Data(-120)),"native wheel input claimed while wheel lacks focus");Drain(wheel);check(wheel.PageIndex==1&&wheel.Surface.PageIndex==1&&wheel.Targets.Contains("avif"),"native scroll changes both page and displayed targets");main.NavigateWheelMouse(0x20A,Data(120));Drain(wheel);check(wheel.PageIndex==0,"native reverse scroll returns to page one");main.NavigateWheelMouse(0x20E,Data(120));Drain(wheel);check(wheel.PageIndex==1,"horizontal right scroll advances page");
  using(var hook=new WheelKeyHook(main,false)){foreach(int key in new[]{0x27,0x28,0x22,0x25,0x26,0x21}){int before=wheel.PageIndex;check(hook.Route(0x100,new WheelKeyHook.KeyInfo(){key=(uint)key}),"keyboard hook claims navigation key "+key);Drain(wheel);check(wheel.PageIndex==(before+WheelNavigation.Direction(key)+wheel.PageCount)%wheel.PageCount,"keyboard hook navigates without focus "+key);check(hook.Route(0x101,new WheelKeyHook.KeyInfo(){key=(uint)key}),"matching navigation key release consumed "+key);}check(!hook.Route(0x100,new WheelKeyHook.KeyInfo(){key=0x41}),"ordinary typing is not intercepted");check(hook.Route(0x100,new WheelKeyHook.KeyInfo(){key=0x27,flags=0x10}),"software keyboard navigation supported while wheel is open");Drain(wheel);hook.Route(0x101,new WheelKeyHook.KeyInfo(){key=0x27,flags=0x10});}
  wheel.ChangePage(-wheel.PageIndex);var mouseEvent=new MouseWheelEventArgs(Mouse.PrimaryDevice,Environment.TickCount,-120){RoutedEvent=Mouse.PreviewMouseWheelEvent};wheel.RaiseEvent(mouseEvent);check(mouseEvent.Handled&&wheel.PageIndex==1,"WPF preview scroll fallback advances exactly one page");var keyEvent=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(wheel),Environment.TickCount,Key.PageDown){RoutedEvent=Keyboard.PreviewKeyDownEvent};wheel.RaiseEvent(keyEvent);check(keyEvent.Handled&&wheel.PageIndex==2,"WPF preview keyboard fallback works");
  wheel.ChangePage(-wheel.PageIndex);main.Pref.Gesture=false;using(var nativeMouse=new Hook(main))using(var nativeKeys=new WheelKeyHook(main)){check(nativeMouse.IsInstalled&&nativeKeys.IsInstalled,"real Windows mouse and keyboard hooks installed");var scrollInput=new NativeInput(){type=0,mouse=new NativeMouse(){data=unchecked((uint)-120),flags=0x0800}};check(SendInput(1,new[]{scrollInput},40)==1,"send native vertical wheel message");PumpUntil(wheel,()=>wheel.PageIndex==1);check(wheel.PageIndex==1,"real low-level mouse hook advances wheel with background focus");var down=new NativeInput(){type=1,key=new NativeKey(){vk=0x27}};var up=new NativeInput(){type=1,key=new NativeKey(){vk=0x27,flags=2}};check(SendInput(2,new[]{down,up},40)==2,"send native right-arrow press and release");PumpUntil(wheel,()=>wheel.PageIndex==2);check(wheel.PageIndex==2,"real low-level keyboard hook advances wheel with background focus");}
  wheel.Cancel();check(!main.NavigateWheelMouse(0x20A,Data(-120))&&!main.NavigateWheelKey(0x27),"closed wheel no longer claims background input");var one=new RadialCompass(new[]{"note.txt"},new List<Route>{new Route("zip","","")},"Mixed",0,null,true);one.Show();main.activeWheel=one;main.NavigateWheelMouse(0x20A,Data(-120));Drain(one);check(one.PageCount==1&&one.PageIndex==0&&one.Surface.PageCount==1,"single-page mode remains stable and reports one page");one.Cancel();background.Close();main.Close();File.WriteAllLines(Path.Combine(dir,"navigation-tests.txt"),log);app.Shutdown();return 0;
 }catch(Exception ex){log.Add(ex.ToString());File.WriteAllLines(Path.Combine(dir,"navigation-tests.txt"),log);if(app!=null)app.Shutdown();return 1;}}
}
}
